message.content:
这是为您生成的一页可直接运行的 HTML 演示页面，作为镜桥产品体验日方案的封面。它用信息层级清晰的版式呈现主题、受众、资料来源与日期占位，适合内部预览。
```html
<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<style>
  html,body{margin:0;padding:0;overflow:hidden;background:#F5F2E9;}
  *{box-sizing:border-box;}
  :root{
    --bg:#F5F2E9;--ink:#1B2620;--muted:#5C665D;
    --olive:#4F5E43;--gold:#B4914A;--slate:#8C9FB2;--line:#A3AC9E;
  }
  .slide{
    position:relative;width:1920px;height:1080px;overflow:hidden;
    background:var(--bg);color:var(--ink);
    font-family:"Helvetica Neue",Arial,"PingFang SC","Microsoft YaHei",sans-serif;
  }

  /* ---------- 背景纸面 ---------- */
  .bg-field{position:absolute;inset:0;z-index:0;background:
    radial-gradient(1100px 780px at 2% 0%,rgba(180,145,74,.10),transparent 70%),
    radial-gradient(880px 760px at 46% 48%,rgba(140,159,178,.11),transparent 70%),
    radial-gradient(980px 780px at 96% 96%,rgba(79,94,67,.11),transparent 72%),
    linear-gradient(168deg,#F8F5EC 0%,#F5F2E9 52%,#EEEBDF 100%);}
  .bg-field:after{content:"";position:absolute;inset:0;
    background:repeating-linear-gradient(90deg,rgba(27,38,32,.045) 0 1px,transparent 1px 160px);opacity:.85;}

  .gridline{position:absolute;top:0;width:1px;height:1080px;z-index:1;background:rgba(27,38,32,.055);}
  .gl1{left:480px}.gl2{left:960px}.gl3{left:1440px}

  .prism{position:absolute;z-index:1;left:1178px;top:-240px;width:180px;height:1560px;
    transform:rotate(15deg);transform-origin:top left;
    background:linear-gradient(180deg,rgba(140,159,178,.24),rgba(140,159,178,.09) 72%,rgba(140,159,178,0));}
  .prism:after{content:"";position:absolute;left:100px;top:0;width:76px;height:1560px;background:rgba(255,255,255,.40);}

  .dot-field{position:absolute;z-index:1;opacity:.22;
    background-image:radial-gradient(circle,rgba(27,38,32,.45) 1.05px,transparent 1.15px);
    background-size:15px 15px;}
  .dot-a{left:60px;top:860px;width:640px;height:220px}
  .dot-b{left:1460px;top:880px;width:420px;height:180px;opacity:.15}

  /* ---------- 右上角刻度圆 ---------- */
  .register{position:absolute;right:-130px;top:-150px;width:430px;height:430px;z-index:2;border-radius:50%;
    border:1px solid rgba(27,38,32,.34);}
  .register .r2{position:absolute;inset:14px;border-radius:50%;border:1px solid rgba(27,38,32,.18);}
  .register .r3{position:absolute;inset:34px;border-radius:50%;
    background:conic-gradient(from 210deg,rgba(79,94,67,.20),rgba(79,94,67,0) 24%,rgba(140,159,178,.30) 50%,rgba(140,159,178,.08) 78%,rgba(79,94,67,.20));}
  .register .r4{position:absolute;inset:48px;border-radius:50%;background:rgba(245,242,233,.90);
    border:1px solid rgba(27,38,32,.08);}
  .register .r5{position:absolute;inset:70px;border-radius:50%;background:rgba(140,159,178,.26);
    border:1px solid rgba(27,38,32,.09);}
  .register .dot{position:absolute;left:96px;top:296px;width:15px;height:15px;border-radius:50%;
    background:var(--gold);box-shadow:0 0 0 6px rgba(180,145,74,.14);}

  /* ---------- 顶部标尺与元信息 ---------- */
  .top-rule{position:absolute;left:96px;top:48px;width:1760px;height:1px;z-index:6;background:rgba(27,38,32,.34);}
  .top-meta{position:absolute;left:96px;top:68px;z-index:15;font-size:15px;font-weight:600;
    letter-spacing:5px;color:#4F5B53;}
  .top-meta .sep{color:var(--gold);margin:0 14px;}

  .left-rule{position:absolute;left:60px;top:40px;width:1px;height:1000px;z-index:6;background:rgba(27,38,32,.24);}
  .rail-tick{position:absolute;left:54px;width:13px;height:1px;z-index:7;background:rgba(27,38,32,.42);}
  .rail-tick.t1{top:180px}.rail-tick.t2{top:560px}.rail-tick.t3{top:940px}
  .rail-label{position:absolute;left:42px;top:562px;width:420px;z-index:15;
    transform:rotate(-90deg);transform-origin:left top;
    font-size:13px;font-weight:600;letter-spacing:6px;color:#637067;white-space:nowrap;}

  /* ---------- 主标题区 ---------- */
  .kicker{position:absolute;left:100px;top:292px;z-index:10;
    font-size:16px;font-weight:700;letter-spacing:6px;color:var(--olive);}
  .kicker .bar{display:inline-block;width:44px;height:2px;background:var(--gold);
    vertical-align:middle;margin-right:18px;transform:translateY(-3px);}

  h1{position:absolute;left:96px;top:336px;margin:0;z-index:10;
    font-family:Georgia,"Songti SC","SimSun","Noto Serif CJK SC",serif;
    font-size:124px;line-height:1.14;font-weight:700;letter-spacing:5px;
    color:#17211C;}

  .title-rule{position:absolute;left:100px;top:566px;width:260px;height:3px;z-index:10;background:var(--gold);}

  .subtitle{position:absolute;left:100px;top:602px;z-index:10;
    font-size:31px;font-weight:500;letter-spacing:2px;color:#3E4A42;}
  .subtitle-sub{position:absolute;left:100px;top:656px;z-index:10;
    font-size:19px;letter-spacing:3px;color:var(--muted);}

  /* ---------- 右侧大字水印 ---------- */
  .ghost-no{position:absolute;right:74px;top:588px;z-index:3;
    font-family:Georgia,serif;font-size:420px;line-height:1;font-weight:700;
    letter-spacing:-8px;color:rgba(27,38,32,.052);}

  /* ---------- 底部信息条 ---------- */
  .foot-rule{position:absolute;left:96px;top:812px;width:1760px;height:1px;z-index:9;background:rgba(27,38,32,.30);}
  .foot{position:absolute;left:100px;top:846px;width:1640px;z-index:12;display:flex;}
  .foot .cell{width:410px;padding-right:36px;}
  .foot .cell .lab{font-size:13px;font-weight:700;letter-spacing:4px;color:#6C7A70;margin-bottom:12px;}
  .foot .cell .val{font-size:20px;line-height:1.5;color:#26312B;letter-spacing:.6px;}
  .foot .cell .val.small{font-size:18px;color:#3B4740;}
  .foot .cell .val.pending{color:var(--gold);font-weight:700;letter-spacing:2px;}

  /* ---------- 页码 ---------- */
  .page-no{position:absolute;right:96px;bottom:46px;z-index:20;
    font-size:15px;font-weight:700;letter-spacing:4px;color:#6A776D;}
  .page-no .slash{color:var(--gold);margin:0 8px;}
</style>
</head>
<body>
<main class="slide">
  <div class="bg-field"></div>
  <div class="gridline gl1"></div>
  <div class="gridline gl2"></div>
  <div class="gridline gl3"></div>
  <div class="prism"></div>
  <div class="dot-field dot-a"></div>
  <div class="dot-field dot-b"></div>

  <div class="register">
    <div class="r2"></div>
    <div class="r3"></div>
    <div class="r4"></div>
    <div class="r5"></div>
    <div class="dot"></div>
  </div>

  <div class="top-rule"></div>
  <div class="left-rule"></div>
  <div class="rail-tick t1"></div>
  <div class="rail-tick t2"></div>
  <div class="rail-tick t3"></div>

  <div class="top-meta">镜桥 <span class="sep">/</span> 方案稿 <span class="sep">/</span> 会前阅读材料</div>
  <div class="rail-label">MIRROR&nbsp;BRIDGE&nbsp;&nbsp;·&nbsp;&nbsp;产品体验日</div>

  <div class="kicker"><span class="bar"></span>PRODUCT EXPERIENCE DAY</div>
  <h1>镜桥产品体验日方案</h1>
  <div class="title-rule"></div>
  <div class="subtitle">面向企业市场活动执行团队</div>
  <div class="subtitle-sub">依据附件 campaign.pdf 整理，仅含资料所述内容</div>

  <div class="ghost-no">01</div>

  <div class="foot-rule"></div>
  <div class="foot">
    <div class="cell">
      <div class="lab">资料来源</div>
      <div class="val">campaign.pdf（附件）</div>
    </div>
    <div class="cell">
      <div class="lab">内容范围</div>
      <div class="val">仅含资料所述内容</div>
    </div>
    <div class="cell">
      <div class="lab">资料性质</div>
      <div class="val small">虚构测评材料，所有数值为测试构造值</div>
    </div>
    <div class="cell">
      <div class="lab">活动日期</div>
      <div class="val pending">待确认</div>
    </div>
  </div>

  <div class="page-no">1<span class="slash">/</span>6</div>
</main>
</body>
</html>
```
